"""Write docs/imports.md from the ledger (split from importer.py; was `importer.py report`).

    python report.py [--lock-wait S] [--agent NAME]
"""
import collections
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.dirname(os.path.dirname(HERE))
if HERE not in sys.path:
    sys.path.insert(0, HERE)
from libdefs import COPY_COMMIT, COPY_NAME  # noqa: E402
from ledger import RECONSTRUCTED, load_state  # noqa: E402


def report(state):
    lines = ['# Imported Westwood libraries', '',
             'Generated by `tools/vc6/report.py` from the ledger `docs/data/imports`. Each library '
             'was imported from EA\'s published copies (R Renegade, G Generals, Z Zero Hour; commits '
             + ', '.join(f'{COPY_NAME[c]} `{COPY_COMMIT[c]}`' for c in 'RGZ') + '), file by file, '
             'keeping the copy whose compiled code matches client.exe best, then splicing in whole '
             'function definitions from other copies where that adds byte-exact functions without '
             'losing any. "In tree": client functions our own source reproduces byte for byte '
             '(compiled with VC6 SP4, `/MT /W3 /O2 /Ob2`). See docs/library-matching.md Â§3.5.', '']
    lines += ['## Summary', '', '"Exact, ambiguous address" (D54): functions whose compiled bytes occur at several places '
              'in client.exe, all copies identical (relocated fields included), so no single address can be '
              'credited; counted once per client function, never as pairs.', '',
              '| Library | Base copy | Source files | From another copy | Functions merged | In tree | Exact, ambiguous address | Best single copy |',
              '|---|---|---|---|---|---|---|---|']
    for lib, s in state.items():
        files = s['files']
        other = sum(1 for f in files.values() if f['copy'] != s['base'])
        merged = sum(len(f['merged']) for f in files.values())
        lines.append(f"| {lib} | {COPY_NAME[s['base']]} | {len(files)} | {other} | {merged} | "
                     f"{s.get('in_tree_total', '?')} | {s.get('ambiguous_total', '?')} | {max(s['totals'].values(), default='-')} |")
    lines += ['', '## Local changes', '']
    lines.append('* Each E&B change to an EA-derived file is described in that file\'s end-of-file block of '
                 '`// EnB:` entries (frozen 2026-11-07, D211; docs/conventions.md): `grep -rn "// EnB:"` lists them all.')
    for (lib, name), why in RECONSTRUCTED.items():
        lines.append(f'* `{lib}/{name}`: **reconstructed** from the client. {why}.')
    for lib, s in state.items():
        lines += ['', f'## {lib}', '', f"Base copy: {COPY_NAME[s['base']]}. Headers: "
                  + ', '.join(f'{n} from {COPY_NAME.get(c, c)}' for c, n in
                              collections.Counter(s.get('headers', {}).values()).items()) + '.', '']
        if s.get('compile_errors'):
            lines += ['Compile errors in the tree (first few):', '']
            lines += [f'    {e.strip()[:160]}' for e in s['compile_errors'][:8]] + ['']
        lines += ['| File | From | In tree | Ambiguous | R | G | Z | Merged functions |', '|---|---|---|---|---|---|---|---|']
        for k, f in sorted(s['files'].items()):
            exp = f['expected']
            merged = '; '.join(f"{m['function']} ({m['copy']})" for m in f['merged'])
            lines.append(f"| {f.get('name', k)} | {f['copy']}{'+h' if f.get('headers_from') else ''} | {len(f.get('in_tree', []))} | "
                         f"{len(f['ambiguous']) if 'ambiguous' in f else '?'} | "
                         + ' | '.join(str(exp.get(c, '-')) for c in 'RGZ') + f' | {merged} |')
    open(os.path.join(REPO, 'docs', 'imports.md'), 'w', newline='\n', encoding='utf-8').write('\n'.join(lines) + '\n')
    print('docs/imports.md written')


def main(argv=None):
    import argparse
    import vc6lock
    ap = argparse.ArgumentParser(description='Write docs/imports.md from the ledger.')
    ap.add_argument('--lock-wait', type=int, default=vc6lock.LOCK_WAIT,
                    help='seconds to wait for a verify to finish (default %(default)s)')
    ap.add_argument('--agent', metavar='NAME', help='agent name: the lock owner')
    a = ap.parse_args(argv)
    if a.agent:
        vc6lock.set_agent(a.agent)
    vc6lock.hold_lock(a.lock_wait)
    report(load_state())


if __name__ == '__main__':
    main()
